using System;
using DenTinh.Core;
public static class ShadowTests {
    static int checks;
    static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
    static Simulation Arena(string hero="quanle"){Simulation g=new Simulation(CatalogData.Create(),hero,71426);g.Enemies.Clear();g.Props.Clear();g.Drops.Clear();g.Player.position=new V2(25,20);g.Player.crit=0;g.Player.invulnerable=0;g.Input=new GameInput{aim=new V2(28,20)};g.Tutorial=5;return g;}
    static EnemyState Enemy(Simulation g,float x=26,float y=20){EnemyState e=g.Spawn("slime",new V2(x,y),false);e.hp=e.maxHp=1000000;e.damage=e.speed=0;e.cooldown=999;return e;}
    static void Tick(Simulation g,float seconds){for(int i=0;i<Math.Ceiling(seconds/.02f);i++)g.Tick(.02f);}
    static void Reset(Simulation g){g.Player.action=null;g.Player.qTimer=g.Player.eTimer=g.Player.fireTimer=0;g.Player.mp=100;g.Player.ult=100;g.Player.rCd=0;g.Player.ultIntro=null;}
    public static int Main(){try{
        ContentDatabase db=CatalogData.Create();Simulation g=Arena("kiet");Check(g.Hero.id=="quanle"&&g.Hero.name=="Quân Lê"&&g.Weapon.id=="shadow-crescent"&&db.shadows.Length==22,"Old alias selects canonical Quân Lê and shadow weapon");
        g.Player.qRank=2;Check(g.Skill("q")&&g.Player.shadowArmor==6.5f&&g.Player.shield==68,"Q armor and shield apply immediately");Simulation plain=Arena();g.Player.shield=0;g.Player.hp=plain.Player.hp=50;g.DamagePlayer(20);plain.DamagePlayer(20);Check(Math.Abs((50-g.Player.hp)/(50-plain.Player.hp)-.65f)<.0001f&&g.Effects.Exists(fx=>fx.clip=="shadow_counter"),"Armor reduces damage 35 percent and counterattacks");EnemyState e=Enemy(g);float hp=g.Player.hp;Tick(g,.5f);Check(e.hp<e.maxHp&&g.Player.hp>hp,"Armor tendrils damage and heal");float remaining=g.Player.shadowArmor;g.Paused=true;g.Tick(1);Check(g.Player.shadowArmor==remaining,"Pause freezes shadow timers");g.Paused=false;Tick(g,7);Check(g.Player.shadowArmor==0,"Armor expires");
        g=Arena();e=Enemy(g);e.hp=1;g.DamageEnemy(e,2,false);g.DamageEnemy(e,2,false);Check(g.ShadowRemains.Count==1&&g.ShadowRemains[0].life==20,"Enemy leaves exactly one soul");foreach(string type in new[]{"tree","bamboo","willow","banyan","pine","deadTree"}){Prop p=new Prop{type=type,position=new V2(26,20),damageStage=2};g.RecordShadow(p);g.RecordShadow(p);}Check(g.ShadowRemains.Count==7,"Six tree families produce one soul each");
        g=Arena();Prop tree=new Prop{type="willow",position=new V2(26,20),damageStage=2};g.Props.Add(tree);Check(g.Skill("e"),"E accepts cast");Check(g.ShadowArmy.Count==1&&g.ShadowArmy[0].kind=="shadow_treant"&&g.ShadowRemains[0].life==0,"E consumes nearby tree soul at corpse location");for(int i=0;i<7;i++){Reset(g);g.Skill("e");}Check(g.ShadowArmy.Count==6&&g.ShadowArmy.Exists(s=>s.power>g.Player.damage),"E cap six refreshes and empowers oldest body");
        g=Arena();for(int i=0;i<20;i++)g.RecordShadow(new Prop{type="tree",damageStage=2,position=new V2(25+i*.01f,20)});Reset(g);g.Skill("r");Tick(g,4.48f);Check(g.ShadowArmy.Count==0&&g.Player.ultIntro!=null,"Legion waits for intro");Tick(g,.02f);Check(g.ShadowArmy.Count==14&&g.ShadowFrenzy==24&&g.Player.rCd>15&&g.ShadowRemains.TrueForAll(r=>r.life==0),"R consumes souls and creates bounded 24 second legion");e=Enemy(g);Tick(g,2);Check(e.hp<e.maxHp&&Math.Abs(g.Player.rCd-13.5f)<.04f,"Legion fights autonomously without cooldown feedback");Tick(g,24);Check(g.ShadowArmy.Count==0,"Legion expires");
        g=Arena();Reset(g);g.Skill("r");Tick(g,6);Check(g.ShadowArmy.TrueForAll(s=>V2.Distance(s.position,g.Player.position)>170/64f),"Idle legion keeps space around hero");
        foreach(ShadowSpec spec in db.shadows){g=Arena();e=Enemy(g);g.Player.hp=40;ShadowUnit s=g.SpawnShadow(spec.id,new V2(25.5f,20));s.spawnAge=.45f;g.ShadowAttack(s,e);Check(e.hp==e.maxHp,spec.id+" waits for anticipation");Tick(g,.4f);Check(e.hp<e.maxHp,spec.id+" attacks");if(spec.behavior=="web")Check(e.rooted>1,"Spider web roots cluster");if(spec.behavior=="venom")Check(e.poison>0&&e.shadowCorrosion>0,"Cobra poison corrodes armor");if(spec.behavior=="siphon")Check(g.Player.hp>40,"Bat siphon heals owner");}
        g=Arena();g.SpawnShadow("shadow_dragon",new V2(26,20));g.Skill("q");RunSave save=g.Capture();save.hero="kiet";save.shadowArmy.Add(new ShadowUnit{kind="invalid",hp=50,life=22});Simulation restored=Simulation.Restore(db,save);Check(restored.Hero.id=="quanle"&&restored.ShadowArmy.Count==1&&restored.Player.shadowArmor==6.5f,"Save restores alias, armor and valid army only");restored.Respawn();Check(restored.ShadowArmy.Count==0&&restored.Player.shadowArmor==0,"Respawn clears shadow state");
        foreach(string form in new[]{"lightning","earth","ice","nature"}){g=Arena("thienvu");g.TransformElement(form);e=Enemy(g);for(int i=0;i<3;i++){Reset(g);g.Fire();Tick(g,.45f);}Check(g.Bullets.Count==0&&e.hp<e.maxHp,form+" melee creates no gun bullets");}
        g=Arena("thienvu");g.TransformElement("light");e=Enemy(g,32);e.facing=0;g.Input=new GameInput{aim=e.position};Check(g.Skill("q")&&g.Player.position.x<e.position.x&&g.Player.position.x>e.position.x-2&&e.hp<e.maxHp&&e.stunned>=.8f&&g.Player.crit==0,"Light Q instantly backstabs within 520 pixels");Check(!g.Effects.Exists(f=>f.clip=="solar_beam"),"Light teleport has no solar beam");
        foreach(string key in new[]{"punch","smash","stomp","throw"}){g=Arena("thienvu");g.CastElement("earth","r",null,new V2(26,20));SummonState s=g.Summons[0];s.spawnAge=.45f;e=Enemy(g,s.position.x+.6f,s.position.y);e.miniBoss=true;EnemyState boss=Enemy(g,s.position.x+3.4f,s.position.y);boss.type="boss";if(key=="stomp")Enemy(g,s.position.x+1,s.position.y+.1f);s.punchCd=s.smashCd=s.stompCd=s.throwCd=999;if(key=="punch")s.punchCd=0;if(key=="smash")s.smashCd=0;if(key=="stomp")s.stompCd=0;if(key=="throw")s.throwCd=0;g.Tick(.02f);Check(s.action!=null&&s.action.clip=="golem_"+key,"Golem AI selects "+key);Tick(g,.24f);if(key=="throw"){Check(s.thrown!=null&&s.thrown.enemy==e,"Golem grabs elite enemy");Tick(g,.9f);Check(!e.shadowHeld&&e.throwLift==0&&boss.hp<boss.maxHp,"Throw lands, releases enemy and damages boss");}Check(g.Decals.Exists(d=>d.type=="crater_mark"),"Golem "+key+" breaks ground");}
        Console.WriteLine(checks+" remaster checks passed");return 0;
    }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
